# owner: platform
"""Build short absence notices to send to parents."""

from typing import List

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

Marks = List[Mark]


def _check_marks(student: Student, marks: Marks) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id!r} given "
                f"with student {student.student_id!r}"
            )


def _absent_days(marks: Marks) -> List[date]:
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to write about")
    return days


def _format_day(when: date) -> str:
    return f"{when:%B} {when.day}, {when.year}"


def _compose(student: Student, days: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    dates = ", ".join(_format_day(when) for when in days)
    noun = "day" if len(days) == 1 else "days"
    head = f"{name} was absent for {len(days)} {noun}."
    return f"{head} Dates: {dates}."


# ---
def build_notice(student: Student, marks: Marks) -> str:
    """Absence notice; ValueError on bad or no marks."""
    marks = list(marks)
    _check_marks(student, marks)
    return _compose(student, _absent_days(marks))
